# ==============================================================================# 094_COMMERCIAL_ACTIVITY_ENGINE.py## IOTEC COMMERCIAL ACTIVITY ENGINE# ==============================================================================from __future__ import annotationsimport sqlite3import uuidimport hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class CommercialActivityEngine:    ACTIVITY_TYPES = [        "CALL",        "EMAIL",        "WHATSAPP",        "MEETING",        "TASK",        "NOTE"    ]    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS commercial_activity(            id INTEGER PRIMARY KEY AUTOINCREMENT,            activity_uuid TEXT UNIQUE,            opportunity_uuid TEXT,            activity_type TEXT,            title TEXT,            description TEXT,            performed_by TEXT,            status TEXT,            scheduled_at TEXT,            completed_at TEXT,            created_at TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ------------------------------------------------------------------    def _sha(self,obj):        raw=json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ------------------------------------------------------------------    def register_activity(        self,        opportunity_uuid,        activity_type,        title,        description,        performed_by="IOTEC"    ):        if activity_type not in self.ACTIVITY_TYPES:            raise RuntimeError("Tipo de atividade inválido.")        payload={            "activity_uuid":str(uuid.uuid4()),            "opportunity_uuid":opportunity_uuid,            "activity_type":activity_type,            "title":title,            "description":description,            "performed_by":performed_by,            "status":"OPEN",            "scheduled_at":None,            "completed_at":None,            "created_at":datetime.utcnow().isoformat(),            "metadata":{                "origin":"094_COMMERCIAL_ACTIVITY_ENGINE"            }        }        assinatura=self._sha(payload)        self.conn.execute("""        INSERT INTO commercial_activity(            activity_uuid,            opportunity_uuid,            activity_type,            title,            description,            performed_by,            status,            scheduled_at,            completed_at,            created_at,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?,?)        """,(            payload["activity_uuid"],            payload["opportunity_uuid"],            payload["activity_type"],            payload["title"],            payload["description"],            payload["performed_by"],            payload["status"],            payload["scheduled_at"],            payload["completed_at"],            payload["created_at"],            json.dumps(payload["metadata"],ensure_ascii=False),            assinatura        ))        self.conn.commit()        return payload# ==============================================================================# TESTE# ==============================================================================if __name__=="__main__":    conn=sqlite3.connect(DB)    conn.row_factory=sqlite3.Row    oportunidade=conn.execute("""        SELECT opportunity_uuid        FROM commercial_pipeline        LIMIT 1    """).fetchone()    if oportunidade is None:        raise RuntimeError("Nenhuma oportunidade encontrada.")    engine=CommercialActivityEngine()    resultado=engine.register_activity(        opportunity_uuid=oportunidade["opportunity_uuid"],        activity_type="TASK",        title="Primeiro contato",        description="Realizar contato inicial com a empresa."    )    print("="*80)    print("COMMERCIAL ACTIVITY")    print("="*80)    for k,v in resultado.items():        print(f"{k:20}: {v}")    print("="*80)